/**
 * The types `save/tier-records/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    TierRecordSaveRow, TierRecordsSaveExtract
 * depends    —
 * used by    src/save/tier-records/index, src/save/tier-records/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

/** A player's records on one tier. */
export interface TierRecordSaveRow {
  tier: number
  highestWave: number | null
  /** Best wave this cycle, from `highestWavePerTierThisCycle`. */
  highestWaveThisCycle: number | null
  roundsStarted: number | null
  highestCoinsEarned: number | null
  highestCellsEarned: number | null
}

export interface TierRecordsSaveExtract {
  /** The tier the player is sitting on, which is often not their highest. */
  currentTier: number | null
  /** Tiers with any record, lowest first. */
  tiers: TierRecordSaveRow[]
}
